<script setup>
import { defineComponent, h, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElDatePicker, ElFormItem, ElInput, ElInputNumber, ElMessage, ElMessageBox, ElOption, ElSelect, ElTableColumn } from 'element-plus'
import { Plus, Save } from 'lucide-vue-next'
import http from '../api/http'

const route=useRoute(),router=useRouter(),editing=ref(Boolean(route.params.bridgeCode)),saving=ref(false),routes=ref([]),bridgeTypes=ref([]),form=reactive({}),structures=reactive({spans:[],structures:[],cables:[],measurementPoints:[]}),archiveRecords=ref([])
const repeatCounts=reactive({deckElevationPoints:0,spans:0,structuralSystems:0,stayCables:0,hangers:0,tieRods:0,expansionJoints:0,railingPositions:0,abutments:0,piers:0,anchors:0,bearings:0})
const make=items=>items.map(([key,label])=>({key,label}))
const areaFields=make([['administrative_code','行政区划代码'],['location_address','桥梁详细地址'],['longitude','经度'],['latitude','纬度']])
const identityFields=make([['pile_number','桥位桩号'],['function_type','功能类型'],['crossed_road_name','被跨越道路名称'],['crossed_road_pile','被跨越道路桩号'],['maintenance_level','养护检查等级'],['built_year','建成年份'],['completion_date','竣工时间'],['design_load','设计荷载'],['bridge_slope','桥梁坡度'],['curve_radius','桥梁平曲线半径'],['design_unit','设计单位'],['construction_unit','施工单位'],['supervision_unit','监理单位'],['owner_unit','业主单位'],['management_unit','管养单位'],['road_management_org','公路管理机构']])
const technicalFields=make([['bridge_length','桥梁全长（m）'],['deck_width','桥面总宽（m）'],['lane_width','车道宽度（m）'],['sidewalk_width','人行道宽度（m）'],['barrier_height','护栏或防撞墙高度（m）'],['median_width','中央分隔带宽度（m）'],['standard_clearance','桥面标准净空（m）'],['actual_clearance','桥面实际净空（m）'],['navigation_standard','桥下通航等级及标准净空（m）'],['navigation_actual','桥下实际净空（m）'],['approach_width','引道总宽（m）'],['approach_alignment','引道线形或曲线半径'],['design_flood','设计洪水频率及水位（cm）'],['historical_flood','历史洪水位（cm）'],['seismic_coefficient','地震动峰值加速度系数（g）']])
const extraFields=make([['span_combination','桥梁分联及跨径组合'],['bridge_engineer','桥梁工程师'],['card_filler','填卡人'],['card_date','填卡日期']])
const structureGroups=[{value:'superstructure',label:'上部结构形式与材料'},{value:'deck',label:'桥面系形式与材料'},{value:'substructure',label:'下部结构形式与材料'},{value:'foundation',label:'基础形式与材料'},{value:'bearing_facility',label:'支座形式、材料与附属设施'}]
const cableTypes=['斜拉索','吊杆','系杆']
const designLoadOptions=['公路-Ⅰ级','公路-Ⅱ级','汽车-超20级','汽车-20级','汽车-15级','挂车-100','挂车-80','城-A级','城-B级']
const decimalFields=new Set(['bridge_length','deck_width','lane_width','sidewalk_width','barrier_height','median_width','approach_width','longitude','latitude'])
const structureTypeOptions={superstructure:['主梁','主拱圈','桥塔','索塔','拱上建筑','主缆','斜拉索','吊杆','系杆','结构体系'],deck:['桥面铺装','伸缩缝','人行道','路缘','栏杆','护栏','照明','标志'],substructure:['桥台','桥墩','锥坡','护坡','翼墙','耳墙'],foundation:['基础','锚碇'],bearing_facility:['支座','防撞设施','航标','排水','检修设施','监测设施','其他附属']}
const dimensionFields=[['deckElevationPoints','桥面高程测点数'],['spans','桥梁分孔数'],['structuralSystems','结构体系种类数'],['stayCables','斜拉索数'],['hangers','吊杆数'],['tieRods','系杆数'],['expansionJoints','伸缩缝数'],['railingPositions','栏杆/护栏部位数'],['abutments','桥台数'],['piers','桥墩数'],['anchors','锚碇数'],['bearings','支座数']].map(([key,label])=>({key,label}))
const EditSection=defineComponent({props:{code:String,title:String,subtitle:String},setup:(p,{slots})=>()=>h('section',{class:'edit-section'},[h('div',{class:'section-head'},[h('b',p.code),h('div',[h('h3',p.title),h('span',p.subtitle)])]),slots.default?.()])})
const Field=defineComponent({props:{item:Object},setup:p=>()=>h(ElFormItem,{label:p.item.label},()=>{const k=p.item.key;if(k==='built_year')return h(ElInputNumber,{modelValue:form.built_year,'onUpdate:modelValue':v=>form.built_year=v,min:1000,max:2100,step:1,controlsPosition:'right',style:'width:100%'});if(k==='completion_date')return h(ElDatePicker,{modelValue:form.completion_date,'onUpdate:modelValue':v=>form.completion_date=v,valueFormat:'YYYY-MM-DD',placeholder:'选择竣工时间',style:'width:100%'});if(k==='design_load')return h(ElSelect,{modelValue:form.design_load,'onUpdate:modelValue':v=>form.design_load=v,filterable:true,allowCreate:true,placeholder:'选择或输入设计荷载',style:'width:100%'},()=>designLoadOptions.map(v=>h(ElOption,{key:v,label:v,value:v})));if(k==='curve_radius')return h(ElSelect,{modelValue:form.curve_radius,'onUpdate:modelValue':v=>form.curve_radius=v,filterable:true,allowCreate:true,placeholder:'∞ 或输入数值',style:'width:100%'},()=>[h(ElOption,{key:'∞',label:'∞',value:'∞'})]);if(decimalFields.has(k))return h(ElInputNumber,{modelValue:form[k],'onUpdate:modelValue':v=>form[k]=v,min:0,precision:k==='longitude'||k==='latitude'?6:2,step:.01,controlsPosition:'right',style:'width:100%'});return h(ElInput,{modelValue:form[k],onInput:v=>form[k]=v})})})
const DetailTitle=defineComponent({emits:['add'],props:{title:String,button:String},setup:(p,{emit})=>()=>h('div',{class:'detail-toolbar'},[h('strong',p.title),h(ElButton,{size:'small',onClick:()=>emit('add')},()=>[h(Plus,{size:14}),p.button])])})
const RemoveColumn=defineComponent({emits:['remove'],setup:(_,{emit})=>()=>h(ElTableColumn,{label:'操作',width:80},{default:scope=>h(ElButton,{text:true,type:'danger',onClick:()=>emit('remove',scope.$index)},()=> '删除')})})

function addMeasurementPoint(){structures.measurementPoints.push({point_category:'deck_elevation',point_no:`测点${structures.measurementPoints.length+1}`,point_name:'',benchmark_elevation:'',remark:''})}
function addSpan(){structures.spans.push({span_no:structures.spans.length+1,span_length:'',structure_form:'',material_type:''})}
function addStructure(group='superstructure'){structures.structures.push({structure_group:group,structure_type:'',serial_no:String(structures.structures.length+1),form:'',material_type:'',quantity:1})}
function addCable(){structures.cables.push({cable_type:'斜拉索',serial_no:String(structures.cables.length+1),force_value:'',material_type:'',location_desc:''})}
function structureRows(group,type){return structures.structures.filter(row=>row.structure_group===group&&row.structure_type===type)}
function cableRows(type){return structures.cables.filter(row=>row.cable_type===type)}
function setRows(target,predicate,count,factory){const current=target.filter(predicate),targetCount=Math.max(0,Number(count)||0);for(let index=target.length-1;current.length>targetCount&&index>=0;index--){if(predicate(target[index])){target.splice(index,1);current.pop()}}for(let index=current.length;index<targetCount;index++)target.push(factory(index+1))}
async function applyCounts(){const reductions=[['测点',structures.measurementPoints.length,repeatCounts.deckElevationPoints],['分孔',structures.spans.length,repeatCounts.spans],['斜拉索',cableRows('斜拉索').length,repeatCounts.stayCables],['吊杆',cableRows('吊杆').length,repeatCounts.hangers],['系杆',cableRows('系杆').length,repeatCounts.tieRods],['桥台',structureRows('substructure','桥台').length,repeatCounts.abutments],['桥墩',structureRows('substructure','桥墩').length,repeatCounts.piers],['锚碇',structureRows('foundation','锚碇').length,repeatCounts.anchors],['支座',structureRows('bearing_facility','支座').length,repeatCounts.bearings]].filter(([,current,next])=>Number(next)<current);if(reductions.length)await ElMessageBox.confirm(`将删除末尾的${reductions.map(([name,current,next])=>`${name}${current-next}条`).join('、')}，保存后不可恢复。`, '确认调整结构数量', {type:'warning',confirmButtonText:'继续调整',cancelButtonText:'取消'});setRows(structures.measurementPoints,()=>true,repeatCounts.deckElevationPoints,index=>({point_category:'deck_elevation',point_no:`测点${index}`,point_name:'',benchmark_elevation:'',remark:''}));setRows(structures.spans,()=>true,repeatCounts.spans,index=>({span_no:index,span_length:'',structure_form:'',material_type:''}));setRows(structures.structures,row=>row.structure_group==='superstructure'&&row.structure_type==='结构体系',repeatCounts.structuralSystems,index=>({structure_group:'superstructure',structure_type:'结构体系',serial_no:`体系${index}`,form:'',material_type:'',quantity:1}));setRows(structures.cables,row=>row.cable_type==='斜拉索',repeatCounts.stayCables,index=>({cable_type:'斜拉索',serial_no:`${index}号索`,force_value:'',material_type:'',location_desc:''}));setRows(structures.cables,row=>row.cable_type==='吊杆',repeatCounts.hangers,index=>({cable_type:'吊杆',serial_no:`${index}号吊杆`,force_value:'',material_type:'',location_desc:''}));setRows(structures.cables,row=>row.cable_type==='系杆',repeatCounts.tieRods,index=>({cable_type:'系杆',serial_no:`${index}号系杆`,force_value:'',material_type:'',location_desc:''}));setRows(structures.structures,row=>row.structure_group==='deck'&&row.structure_type==='伸缩缝',repeatCounts.expansionJoints,index=>({structure_group:'deck',structure_type:'伸缩缝',serial_no:`${index}号`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='deck'&&row.structure_type==='栏杆、护栏',repeatCounts.railingPositions,index=>({structure_group:'deck',structure_type:'栏杆、护栏',serial_no:`部位${index}`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='substructure'&&row.structure_type==='桥台',repeatCounts.abutments,index=>({structure_group:'substructure',structure_type:'桥台',serial_no:`${index}号台`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='substructure'&&row.structure_type==='桥墩',repeatCounts.piers,index=>({structure_group:'substructure',structure_type:'桥墩',serial_no:`${index}号墩`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='foundation'&&row.structure_type==='锚碇',repeatCounts.anchors,index=>({structure_group:'foundation',structure_type:'锚碇',serial_no:`${index}号锚碇`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='bearing_facility'&&row.structure_type==='支座',repeatCounts.bearings,index=>({structure_group:'bearing_facility',structure_type:'支座',serial_no:`${index}号`,form:'',material_type:'',quantity:1}));ElMessage.success('结构明细已按数量生成')}
function syncRepeatCounts(){repeatCounts.deckElevationPoints=structures.measurementPoints?.length||0;repeatCounts.spans=structures.spans.length;repeatCounts.structuralSystems=structureRows('superstructure','结构体系').length;repeatCounts.stayCables=cableRows('斜拉索').length;repeatCounts.hangers=cableRows('吊杆').length;repeatCounts.tieRods=cableRows('系杆').length;repeatCounts.expansionJoints=structureRows('deck','伸缩缝').length;repeatCounts.railingPositions=structureRows('deck','栏杆、护栏').length;repeatCounts.abutments=structureRows('substructure','桥台').length;repeatCounts.piers=structureRows('substructure','桥墩').length;repeatCounts.anchors=structureRows('foundation','锚碇').length;repeatCounts.bearings=structureRows('bearing_facility','支座').length}
async function load(){const [routeData,typeData]=await Promise.all([http.get('/routes',{params:{size:100}}),http.get('/bridge-types',{params:{size:100}})]);routes.value=routeData.records;bridgeTypes.value=typeData.records;if(editing.value){const code=route.params.bridgeCode;Object.assign(form,await http.get(`/bridges/${code}`));Object.assign(structures,await http.get(`/bridge-profiles/${code}/structures`));syncRepeatCounts();await loadArchiveRecords(code);await loadEvaluationRecords(code)}}
async function loadArchiveRecords(bridgeCode){try{const archiveItems=await http.get('/archive-items',{params:{size:50}});const records=await http.get('/archive-records',{params:{bridge_code:bridgeCode,size:50}});archiveRecords.value=archiveItems.records.map(item=>{const existing=records.records.find(r=>r.archive_item_code===item.archive_item_code);return{archive_record_id:existing?.archive_record_id,archive_item_code:item.archive_item_code,archive_item_name:item.archive_item_name,bridge_code:bridgeCode,completeness_status:existing?.completeness_status||'',description:existing?.description||''}})}catch{archiveRecords.value=[]}}
async function initArchiveRecords(){if(!form.bridge_code){ElMessage.warning('请先填写桥梁编号');return}await loadArchiveRecords(form.bridge_code);ElMessage.success('档案项已加载')}
async function save(){if(!form.bridge_code||!form.bridge_name||!form.route_code||!form.bridge_type_code){ElMessage.warning('请填写桥梁编号、名称、路线和桥梁类型');return}saving.value=true;try{let code=form.bridge_code;if(editing.value)await http.put(`/bridges/${route.params.bridgeCode}`,form);else code=(await http.post('/bridges',form)).bridge_code;await http.put(`/bridge-profiles/${code}/structures`,structures);await saveArchiveRecords(code);ElMessage.success('桥梁档案保存成功');router.push(`/bridges/${code}/A`)}finally{saving.value=false}}
async function saveArchiveRecords(bridgeCode){for(const item of archiveRecords.value){const record={bridge_code:bridgeCode,archive_item_code:item.archive_item_code,completeness_status:item.completeness_status||null,description:item.description||null};if(item.archive_record_id)await http.put(`/archive-records/${item.archive_record_id}`,record);else{const created=await http.post('/archive-records',record);item.archive_record_id=created.archive_record_id}}}
onMounted(load)
</script>

